/*!40000 ALTER TABLE `advertisement_translations` DISABLE KEYS */;
INSERT INTO `advertisement_translations` (`id`, `title`, `subtitle`, `description`, `advertisement_id`, `locale`, `created_at`, `updated_at`) VALUES (1,'تذوق كل قضمة','انغمس في التميز في الطهي','<p>استمتع بتجربة سيمفونية من النكهات مع قائمتنا الرائعة التي أعدها طهاة متمرسون. كل طبق عبارة عن تحفة فنية، تم إعداده بدقة ليثير ذوقك ويتركك متشوقًا للمزيد.</p>',1,'ar','2024-12-19 19:32:22','2024-12-19 19:32:22'),(2,'Savor Every Bite','Indulge in Culinary Excellence','<p>Experience a symphony of flavors with our exquisite menu crafted by seasoned chefs. Each dish is a masterpiece, meticulously prepared to tantalize your taste buds and leave you craving for more.</p>',1,'en','2024-12-19 19:32:22','2024-12-19 19:32:22'),(3,'الاسترخاء في الاسلوب','الارتقاء بتجربة تناول الطعام الخاصة بك','<p>اهرب من صخب الحياة اليومية وانغمس في عالم من المطاعم الفاخرة. بدءًا من الأجواء الأنيقة وحتى الخدمة التي لا تشوبها شائبة، تم تصميم كل التفاصيل لضمان استرخائك واستمتاعك.</p>',2,'ar','2024-12-19 19:32:22','2024-12-19 19:32:22'),(4,'Unwind in Style','Elevate Your Dining Experience','<p>Escape the hustle and bustle of daily life and immerse yourself in a world of luxury dining. From elegant ambiance to impeccable service, every detail is designed to ensure your relaxation and enjoyment.</p>',2,'en','2024-12-19 19:32:22','2024-12-19 19:32:22'),(5,'نكهات طازجة في كل وقت','تناول الطعام من المزرعة إلى المائدة في أفضل حالاته','<p>اكتشف الجوهر الحقيقي للنضارة مع مكوناتنا الطازجة من المزرعة والتي يتم الحصول عليها من مصادر محلية. كل طبق هو احتفال بالمنتجات الموسمية، التي تم اختيارها بعناية لتقديم طعم وتغذية لا مثيل لهما.</p>',3,'ar','2024-12-19 19:32:22','2024-12-19 19:32:22'),(6,'Fresh Flavors, Every Time','Farm-to-Table Dining at Its Finest','<p>Discover the true essence of freshness with our farm-fresh ingredients sourced locally. Each dish is a celebration of seasonal produce, carefully selected to deliver unparalleled taste and nutrition.</p>',3,'en','2024-12-19 19:32:22','2024-12-19 19:32:22'),(7,'تذوق التقليد','وصفات أصيلة، مسرات خالدة','<p>انطلق في رحلة طهي عبر أجيال من التقاليد مع وصفاتنا الأصيلة المتوارثة عبر العصور. بدءًا من الأطباق الكلاسيكية المفضلة وحتى التقلبات المعاصرة، يحكي كل طبق قصة من التراث والنكهة.</p>',4,'ar','2024-12-19 19:32:22','2024-12-19 19:32:22'),(8,'Taste the Tradition','Authentic Recipes, Timeless Delights','<p>Embark on a culinary journey through generations of tradition with our authentic recipes passed down through the ages. From classic favorites to contemporary twists, each dish tells a story of heritage and flavor.</p>',4,'en','2024-12-19 19:32:22','2024-12-19 19:32:22'),(9,'احتفل بكل مناسبة','اصنع ذكريات لا تنسى','<p>من التجمعات الحميمة إلى الاحتفالات الكبرى، يعد مطعمنا المكان المثالي لجميع لحظاتك الخاصة. ومن خلال قوائم قابلة للتخصيص وخدمة لا تشوبها شائبة، نضمن أن تكون كل مناسبة ذكرى عزيزة.</p>',5,'ar','2024-12-19 19:32:22','2024-12-19 19:32:22'),(10,'Celebrate Every Occasion','Create Unforgettable Memories','<p>From intimate gatherings to grand celebrations, our restaurant is the perfect venue for all your special moments. With customizable menus and impeccable service, we ensure that every occasion is a cherished memory.</p>',5,'en','2024-12-19 19:32:22','2024-12-19 19:32:22'),(11,'وليمة للحواس','المسرات الحسية في انتظار','<p>انغمس في عالم من المسرات الحسية من خلال عروضنا المذهلة بصريًا، والنكهات العطرية، والقوام المتناغم. كل طبق هو تحفة فنية مصممة لإيقاظ حواسك وإشعال ذوقك.</p>',6,'ar','2024-12-19 19:32:22','2024-12-19 19:32:22'),(12,'A Feast for the Senses','Sensory Delights Await','<p>Immerse yourself in a world of sensory delights with our visually stunning presentations, aromatic flavors, and harmonious textures. Every dish is a masterpiece designed to awaken your senses and ignite your palate.</p>',6,'en','2024-12-19 19:32:22','2024-12-19 19:32:22'),(13,'كوكتيلات مصنوعة، أزواج مثالية','الارتقاء بتجربة تناول الطعام الخاصة بك','<p>عزز رحلتك في الطهي مع الكوكتيلات المصنوعة يدويًا، والتي تم إعدادها بخبرة لتكمل عروض قائمتنا. بدءًا من الخلطات الكلاسيكية إلى الخلطات المبتكرة، كل رشفة هي رحلة اكتشاف ومتعة.</p>',7,'ar','2024-12-19 19:32:22','2024-12-19 19:32:22'),(14,'Crafted Cocktails, Perfect Pairings','Elevate Your Dining Experience','<p>Enhance your culinary journey with our handcrafted cocktails, expertly curated to complement our menu offerings. From classic concoctions to innovative blends, each sip is a journey of discovery and delight.</p>',7,'en','2024-12-19 19:32:22','2024-12-19 19:32:22'),(15,'تناول الطعام المناسب للعائلات','متعة لجميع الأعمار','<p>اصنع ذكريات تدوم مع أحبائك في مطعمنا المناسب للعائلات. بفضل الأجواء الترحيبية وقائمة الطعام التي ترضي حتى أكثر الأشخاص إرضاءً، فإننا نقدم خدماتنا للعائلات من جميع الأحجام والأعمار.</p>',8,'ar','2024-12-19 19:32:22','2024-12-19 19:32:22'),(16,'Family-Friendly Dining','Fun for All Ages','<p>Create lasting memories with your loved ones in our family-friendly restaurant. With a welcoming atmosphere and a menu to please even the pickiest eaters, we cater to families of all sizes and ages.</p>',8,'en','2024-12-19 19:32:22','2024-12-19 19:32:22'),(17,'التجربة المتميزة','حيث يكون كل طبق تحفة فنية','<p>في مطعمنا، التميز ليس مجرد هدف - إنه معيار. بدءًا من المكونات الطازجة إلى أرقى العروض، نسعى جاهدين لتحقيق الكمال في كل جانب من جوانب تجربة تناول الطعام الخاصة بك. تعال وتذوق الفرق اليوم.</p >',9,'ar','2024-12-19 19:32:22','2024-12-19 19:32:22'),(18,'Experience Excellence','Where Every Dish Is a Masterpiece','<p>At our restaurant, excellence is not just a goal – it\'s a standard. From the freshest ingredients to the finest presentation, we strive for perfection in every aspect of your dining experience. Come and taste the difference today.</p>',9,'en','2024-12-19 19:32:22','2024-12-19 19:32:22');
/*!40000 ALTER TABLE `advertisement_translations` ENABLE KEYS */;
UNLOCK TABLES;

