INSERT INTO `categorySkill_translations` (`id`, `title`, `description`, `category_skill_id`, `locale`, `created_at`, `updated_at`) VALUES (1,'ملاكمة','<p>اكتشف مجموعتنا المتنوعة من دروس اللياقة البدنية المصممة لتعزيز مهاراتك وأدائك. بدءًا من تدريب القوة والتكييف وحتى المرونة وخفة الحركة، يقدم المدربون الخبراء لدينا جلسات ديناميكية مصممة لمساعدتك على تحقيق أهداف اللياقة البدنية الخاصة بك وإطلاق العنان لإمكاناتك الكاملة.</p>',1,'ar','2024-12-19 19:32:18','2024-12-19 19:32:18'),(2,'Boxing','<p>Discover our diverse selection of fitness classes tailored to enhance your skills and performance. From strength training and conditioning to flexibility and agility, our expert instructors offer dynamic sessions designed to help you achieve your fitness goals and unlock your full potential.</p>',1,'en','2024-12-19 19:32:18','2024-12-19 19:32:18'),(3,'تَغذِيَة','<p>اكتشف مجموعتنا المتنوعة من دروس اللياقة البدنية المصممة لتعزيز مهاراتك وأدائك. بدءًا من تدريب القوة والتكييف وحتى المرونة وخفة الحركة، يقدم المدربون الخبراء لدينا جلسات ديناميكية مصممة لمساعدتك على تحقيق أهداف اللياقة البدنية الخاصة بك وإطلاق العنان لإمكاناتك الكاملة.</p>',2,'ar','2024-12-19 19:32:18','2024-12-19 19:32:18'),(4,'Nutrition','<p>Discover our diverse selection of fitness classes tailored to enhance your skills and performance. From strength training and conditioning to flexibility and agility, our expert instructors offer dynamic sessions designed to help you achieve your fitness goals and unlock your full potential.</p>',2,'en','2024-12-19 19:32:18','2024-12-19 19:32:18'),(5,'تعليق','<p>اكتشف مجموعتنا المتنوعة من دروس اللياقة البدنية المصممة لتعزيز مهاراتك وأدائك. بدءًا من تدريب القوة والتكييف وحتى المرونة وخفة الحركة، يقدم المدربون الخبراء لدينا جلسات ديناميكية مصممة لمساعدتك على تحقيق أهداف اللياقة البدنية الخاصة بك وإطلاق العنان لإمكاناتك الكاملة.</p>',3,'ar','2024-12-19 19:32:18','2024-12-19 19:32:18'),(6,'Suspension','<p>Discover our diverse selection of fitness classes tailored to enhance your skills and performance. From strength training and conditioning to flexibility and agility, our expert instructors offer dynamic sessions designed to help you achieve your fitness goals and unlock your full potential.</p>',3,'en','2024-12-19 19:32:18','2024-12-19 19:32:18'),(7,'جوهر','<p>اكتشف مجموعتنا المتنوعة من دروس اللياقة البدنية المصممة لتعزيز مهاراتك وأدائك. بدءًا من تدريب القوة والتكييف وحتى المرونة وخفة الحركة، يقدم المدربون الخبراء لدينا جلسات ديناميكية مصممة لمساعدتك على تحقيق أهداف اللياقة البدنية الخاصة بك وإطلاق العنان لإمكاناتك الكاملة.</p>',4,'ar','2024-12-19 19:32:18','2024-12-19 19:32:18'),(8,'Core','<p>Discover our diverse selection of fitness classes tailored to enhance your skills and performance. From strength training and conditioning to flexibility and agility, our expert instructors offer dynamic sessions designed to help you achieve your fitness goals and unlock your full potential.</p>',4,'en','2024-12-19 19:32:18','2024-12-19 19:32:18'),(9,'كيتلبيل','<p>اكتشف مجموعتنا المتنوعة من دروس اللياقة البدنية المصممة لتعزيز مهاراتك وأدائك. بدءًا من تدريب القوة والتكييف وحتى المرونة وخفة الحركة، يقدم المدربون الخبراء لدينا جلسات ديناميكية مصممة لمساعدتك على تحقيق أهداف اللياقة البدنية الخاصة بك وإطلاق العنان لإمكاناتك الكاملة.</p>',5,'ar','2024-12-19 19:32:18','2024-12-19 19:32:18'),(10,'Kettlebell','<p>Discover our diverse selection of fitness classes tailored to enhance your skills and performance. From strength training and conditioning to flexibility and agility, our expert instructors offer dynamic sessions designed to help you achieve your fitness goals and unlock your full potential.</p>',5,'en','2024-12-19 19:32:18','2024-12-19 19:32:18'),(11,'دورة','<p>اكتشف مجموعتنا المتنوعة من دروس اللياقة البدنية المصممة لتعزيز مهاراتك وأدائك. بدءًا من تدريب القوة والتكييف وحتى المرونة وخفة الحركة، يقدم المدربون الخبراء لدينا جلسات ديناميكية مصممة لمساعدتك على تحقيق أهداف اللياقة البدنية الخاصة بك وإطلاق العنان لإمكاناتك الكاملة.</p>',6,'ar','2024-12-19 19:3