INSERT INTO `challenge_translations` (`id`, `title`, `description`, `challenge_id`, `locale`, `created_at`, `updated_at`) VALUES (5,'ماراثون الحلوى','<p>شارك في ماراثون الحلوى من خلال تناول 3 أنواع من الحلوى في زيارة واحدة. احصل على الحلوى الرابعة مجانًا!</p>',3,'ar','2024-12-19 19:32:31','2024-12-19 19:32:31'),(6,'Dessert Marathon','<p>Participate in the Dessert Marathon by eating 3 desserts in one visit. Get the 4th dessert free!</p>',3,'en','2024-12-19 19:32:31','2024-12-19 19:32:31'),(7,'تحدي طبق الشيف المميز','<p>جرب طبق الشيف المميز لهذا اليوم. إذا أكلته بالكامل، ستحصل على خصم خاص!</p>',4,'ar','2024-12-19 19:32:31','2024-12-19 19:32:31'),(8,'Chef\'s Special Challenge','<p>Try the Chef\'s Special of the day. If you finish it all, you\'ll get a special discount!</p>',4,'en','2024-12-19 19:32:31','2024-12-19 19:32:31'),(9,'تحدي الطبق الغامض','<p>اختبر حواس الطعم لديك مع طبق غامض. إذا تعرفت على جميع المكونات، ستحصل على هدية خاصة!</p>',5,'ar','2024-12-19 19:32:31','2024-12-19 19:32:31'),(10,'Mystery Dish Challenge','<p>Challenge your taste buds with a mystery dish. If you identify all the ingredients, you get a special gift!</p>',5,'en','2024-12-19 19:32:31','2024-12-19 19:32:31'),(11,'تحدي الأطعمة النباتية','<p>شارك في تحدي الأطعمة النباتية عن طريق طلب 3 أطباق نباتية مختلفة. احصل على مشروب مجاني!</p>',6,'ar','2024-12-19 19:32:31','2024-12-19 19:32:31'),(12,'Vegan Delight Challenge','<p>Take the Vegan Delight Challenge by ordering 3 different vegan dishes. Get a free drink!</p>',6,'en','2024-12-19 19:32:31','2024-12-19 19:32:31'),(13,'تحدي الوليمة العائلية','<p>اجلب عائلتك واستمتع بتحدي الوليمة العائلية. إذا انتهيتم من الوجبة بالكامل، ستحصلون على خصم 15%!</p>',7,'ar','2024-12-19 19:32:31','2024-12-19 19:32:31'),(14,'Family Feast Challenge','<p>Bring your family and enjoy the Family Feast Challenge. Finish the entire meal and get a 15% discount!</p>',7,'en','2024-12-19 19:32:31','2024-12-19 19:32:31'),(15,'جولة المأكولات العالمية','<p>سافر حول العالم مع جولة المأكولات العالمية. جرب 3 أطباق من مطابخ مختلفة واحصل على تذكار خاص!</p>',8,'ar','2024-12-19 19:32:31','2024-12-19 19:32:31'),(16,'Global Cuisine Tour','<p>Travel the world with the Global Cuisine Tour. Try 3 dishes from different cuisines and receive a special souvenir!</p>',8,'en','2024-12-19 19:32:31','2024-12-19 19:32:31'),(17,'تحدي الأكل الصحي','<p>انضم إلى تحدي الأكل الصحي عن طريق طلب 3 أطباق صحية. احصل على نصيحة غذائية مجانية من الشيف!</p>',9,'ar','2024-12-19 19:32:31','2024-12-19 19:32:31'),(18,'Healthy Eating Challenge','<p>Join the Healthy Eating Challenge by ordering 3 healthy dishes. Get a free nutrition tip from the chef!</p>',9,'en','2024-12-19 19:32:31','2024-12-19 19:32:31'),(19,'سيلفي مع الشيف','<p>التقط سيلفي مع الشيف وانشره على وسائل التواصل الاجتماعي باستخدام هاشتاج #مطعمنا. احصل على خصم 5% على وجبتك القادمة!</p>',10,'ar','2024-12-19 19:32:31','2024-12-19 19:32:31'),(20,'Selfie with the Chef','<p>Take a selfie with the chef and post it on social media with the hashtag #OurRestaurant. Get a 5% discount on your next visit!</p>',10,'en','2024-12-19 19:32:31','2024-12-19 19:32:31');
/*!40000 ALTER TABLE `challenge_translations` ENABLE KEYS */;
UNLOCK TABLES;

