INSERT INTO `chooseus_translations` (`id`, `title`, `description`, `locale`, `chooseus_id`, `created_at`, `updated_at`) VALUES (1,'لماذا يجب أن أختار نجوم العالم  لرحلة اللياقة البدنية الخاصة بي؟','<p>في نجوم العالم ، نقدم تجربة لياقة بدنية شاملة تميزنا عن غيرنا. بدءًا من المرافق الحديثة وحتى توجيهات الخبراء وخيارات التدريب المتنوعة، نحن ملتزمون بنجاحك ورفاهيتك.</p>','ar',1,'2024-12-19 19:32:22','2024-12-19 19:32:22'),(2,'Why should I choose World PT Superstars for my fitness journey?','<p>At World PT Superstars, we offer a comprehensive fitness experience that sets us apart. From state-of-the-art facilities to expert guidance and diverse training options, we are committed to your success and well-being.</p>','en',1,'2024-12-19 19:32:22','2024-12-19 19:32:22'),(3,'ما الذي يجعل صالة الألعاب الرياضية الخاصة بك مختلفة عن الآخرين؟','<p>تتميز صالة الألعاب الرياضية لدينا بأجواء مجتمعية نابضة بالحياة وبرامج مبتكرة والتزام بتوفير بيئة نظيفة وآمنة. نحن نركز على تقديم نهج شامل للياقة البدنية يمتد إلى ما هو أبعد من إجراءات التمرين التقليدية.</p>','ar',2,'2024-12-19 19:32:22','2024-12-19 19:32:22'),(4,'What makes your gym different from others?','<p>Our gym stands out with a vibrant community atmosphere, innovative programs, and a commitment to providing a clean and safe environment. We focus on offering a holistic fitness approach that extends beyond traditional workout routines.</p>','en',2,'2024-12-19 19:32:22','2024-12-19 19:32:22'),(5,'كيف يدعم نجوم العالم  أعضائه في تحقيق أهداف اللياقة البدنية الخاصة بهم؟','<p>يقدم متخصصو اللياقة البدنية المعتمدون لدينا إرشادات شخصية ويضعون خطط تمرين مخصصة. نحن نؤمن بالنهج المبني على النتائج، ونقدم أحدث اتجاهات اللياقة البدنية ونضمن حصول أعضائنا على الأدوات والدعم الذي يحتاجونه لتحقيق النجاح.</p>','ar',3,'2024-12-19 19:32:22','2024-12-19 19:32:22'),(6,'How does World PT Superstars support its members in achieving their fitness goals?','<p>Our certified fitness professionals provide personalized guidance and create customized workout plans. We believe in a results-driven approach, offering the latest in fitness trends and ensuring our members have the tools and support they need to succeed.</p>','en',3,'2024-12-19 19:32:22','2024-12-19 19:32:22');
/*!40000 ALTER TABLE `chooseus_translations` ENABLE KEYS */;
UNLOCK TABLES;

