INSERT INTO `event_translations` (`id`, `title`, `description`, `event_id`, `locale`, `created_at`, `updated_at`) VALUES (5,'تجربة طاولة الشيف','<p>جرب تجربة طاولة الشيف الحصرية حيث يتم إعداد وجبتك أمامك مباشرة بواسطة شيفنا الماهر.</p>',3,'ar','2024-12-19 19:32:31','2024-12-19 19:32:31'),(6,'Chef\'s Table Experience','<p>Experience the exclusive Chef\'s Table where your meal is prepared right in front of you by our skilled chef.</p>',3,'en','2024-12-19 19:32:31','2024-12-19 19:32:31'),(7,'يوم المرح العائلي','<p>استمتع بيوم مليء بالمرح والأنشطة لجميع أفراد العائلة. تتضمن الفعاليات ألعاب الأطفال والمسابقات والجوائز.</p>',4,'ar','2024-12-19 19:32:31','2024-12-19 19:32:31'),(8,'Family Fun Day','<p>Enjoy a day filled with fun activities for the whole family. Events include kids\' games, contests, and prizes.</p>',4,'en','2024-12-19 19:32:31','2024-12-19 19:32:31'),(9,'ليلة التوافه','<p>اختبر معلوماتك واستمتع بليلة مليئة بالمرح في ليلة التوافه. جوائز قيمة بانتظار الفائزين!</p>',5,'ar','2024-12-19 19:32:31','2024-12-19 19:32:31'),(10,'Trivia Night','<p>Test your knowledge and have fun at Trivia Night. Great prizes await the winners!</p>',5,'en','2024-12-19 19:32:31','2024-12-19 19:32:31'),(11,'صف طهي','<p>تعلم أسرار الطهي من شيفنا الماهر في صف الطهي الخاص بنا. احجز مكانك الآن!</p>',6,'ar','2024-12-19 19:32:31','2024-12-19 19:32:31'),(12,'Cooking Class','<p>Learn cooking secrets from our skilled chef in our special cooking class. Reserve your spot now!</p>',6,'en','2024-12-19 19:32:31','2024-12-19 19:32:31'),(13,'ليلة الكاريوكي','<p>شارك في ليلة الكاريوكي وأظهر مهاراتك الغنائية. ليلة مليئة بالمرح والأغاني!</p>',7,'ar','2024-12-19 19:32:31','2024-12-19 19:32:31'),(14,'Karaoke Night','<p>Participate in Karaoke Night and show off your singing skills. A fun night full of songs and entertainment!</p>',7,'en','2024-12-19 19:32:31','2024-12-19 19:32:31'),(15,'عشاء خيري','<p>انضم إلينا في عشاء خيري حيث تذهب جميع العائدات لدعم القضايا الخيرية. احجز طاولتك وادعم العمل الخيري.</p>',8,'ar','2024-12-19 19:32:31','2024-12-19 19:32:31'),(16,'Charity Dinner','<p>Join us for a charity dinner where all proceeds go to support charitable causes. Reserve your table and support the cause.</p>',8,'en','2024-12-19 19:32:31','2024-12-19 19:32:31'),(17,'مهرجان الطعام الموسمي','<p>استمتع بمهرجان الطعام الموسمي حيث نقدم مجموعة من الأطباق الخاصة بمناسبة الموسم. لا تفوت الفرصة!</p>',9,'ar','2024-12-19 19:32:31','2024-12-19 19:32:31'),(18,'Seasonal Food Festival','<p>Enjoy a Seasonal Food Festival featuring a variety of dishes celebrating the season. Don\'t miss out!</p>',9,'en','2024-12-19 19:32:31','2024-12-19 19:32:31'),(19,'معرض الفن والعشاء','<p>استمتع بليلة من الفن والطعام في معرض الفن والعشاء الخاص بنا. فرصة لمشاهدة الأعمال الفنية الرائعة وتذوق الأطباق الشهية.</p>',10,'ar','2024-12-19 19:32:31','2024-12-19 19:32:31'),(20,'Art Exhibition and Dinner','<p>Enjoy a night of art and dining at our Art Exhibition and Dinner event. A chance to view amazing artworks and taste delicious dishes.</p>',10,'en','2024-12-19 19:32:31','2024-12-19 19:32:31');
/*!40000 ALTER TABLE `event_translations` ENABLE KEYS */;
UNLOCK TABLES;

