INSERT INTO `feature_translations` (`id`, `title`, `description`, `locale`, `feature_id`, `created_at`, `updated_at`) VALUES (1,'سنوات الخبرة','<p>لقد خدم سوبر ماركتنا المجتمع بكل فخر لمدة 10 سنوات. ومع إرث مبني على الجودة والموثوقية والخدمة الاستثنائية، فإننا نواصل كوننا وجهتك الموثوقة لجميع احتياجات البقالة الخاصة بك.</p>','ar',1,'2024-12-19 19:32:18','2024-12-19 19:32:18'),(2,'Business Years','<p>Our supermarket has proudly served the community for 10 years. With a legacy built on quality, reliability, and exceptional service, we continue to be your trusted destination for all your grocery needs.</p>','en',1,'2024-12-19 19:32:18','2024-12-19 19:32:18'),(3,'مبيعات المنتجات','<p>استكشف قسم مبيعات المنتجات لدينا للحصول على عروض وخصومات لا تقبل المنافسة على مجموعة واسعة من العناصر عالية الجودة. من المنتجات الطازجة إلى الضروريات المنزلية وغيرها، اكتشف توفيرًا كبيرًا دون المساس بالجودة. أسرع للحصول على عروض لفترة محدودة وصفقات رائعة على منتجاتك المفضلة!.</p>','ar',2,'2024-12-19 19:32:18','2024-12-19 19:32:18'),(4,'Products Sales','<p>Explore our Products Sales section for unbeatable deals and discounts on a wide range of quality items. From fresh produce to household essentials and beyond, discover great savings without compromising on quality. Hurry in for limited-time offers and fantastic bargains on your favorite products!.</p>','en',2,'2024-12-19 19:32:18','2024-12-19 19:32:18'),(5,'عملائنا','<p>قسم العملاء السعداء يحتفل بكم! نحن نفخر بتقديم خدمة استثنائية ومنتجات عالية الجودة ترسم البسمة على وجوه عملائنا. انضم إلى عدد لا يحصى من المتسوقين الراضين الذين يثقون بنا للحصول على تجربة تسوق ممتعة في كل زيارة. رضاكم هو أولويتنا!</p>','ar',3,'2024-12-19 19:32:18','2024-12-19 19:32:18'),(6,'Happy Customers','<p>Our Happy Customers section celebrates YOU! We take pride in delivering exceptional service and quality products that bring smiles to our customers\' faces. Join the countless satisfied shoppers who trust us for a delightful shopping experience every visit. Your satisfaction is our priority!</p>','en',3,'2024-12-19 19:32:18','2024-12-19 19:32:18');
/*!40000 ALTER TABLE `feature_translations` ENABLE KEYS */;
UNLOCK TABLES;

