INSERT INTO `gift_translations` (`id`, `title`, `description`, `gift_id`, `locale`, `created_at`, `updated_at`) VALUES (3,'خصم 10% على وجبتك التالية','<p>احصل على خصم 10% على فاتورتك بالكامل في زيارتك القادمة. شكرًا لكونك أحد العملاء الكرام!</p>',2,'ar','2024-12-19 19:32:31','2024-12-19 19:32:31'),(4,'10% Off Your Next Meal','<p>Get 10% off your entire bill on your next visit. Thank you for being a valued customer!</p>',2,'en','2024-12-19 19:32:31','2024-12-19 19:32:31'),(5,'مقبلات مجانية','<p>ابدأ وجبتك بمقبلات مجانية من اختيارك. متعتنا!</p>',3,'ar','2024-12-19 19:32:31','2024-12-19 19:32:31'),(6,'Free Appetizer','<p>Kick off your meal with a free appetizer of your choice. Our treat!</p>',3,'en','2024-12-19 19:32:31','2024-12-19 19:32:31'),(7,'اشتري واحدة واحصل على واحدة مجانا','<p>اشترِ طبقًا رئيسيًا واحصل على طبق آخر بنفس القيمة أو أقل مجانًا. مثالي للمشاركة!</p>',4,'ar','2024-12-19 19:32:31','2024-12-19 19:32:31'),(8,'Buy One Get One Free','<p>Buy one entrée and get a second entrée of equal or lesser value for free. Perfect for sharing!</p>',4,'en','2024-12-19 19:32:31','2024-12-19 19:32:31'),(9,'المشروبات المجانية','<p>استمتع بمشروب مجاني مع وجبتك. اختر من بين مجموعتنا المختارة من المشروبات الغازية والشاي والمزيد.</p>',5,'ar','2024-12-19 19:32:31','2024-12-19 19:32:31'),(10,'Free Beverage','<p>Enjoy a complimentary beverage with your meal. Choose from our selection of sodas, teas, and more.</p>',5,'en','2024-12-19 19:32:31','2024-12-19 19:32:31'),(11,'خصم 5 دولارات على عملية الشراء التالية','<p>وفّر 5 دولارات عند زيارتك القادمة لمطعمنا. نحن نقدر ولائك!</p>',6,'ar','2024-12-19 19:32:31','2024-12-19 19:32:31'),(12,'$5 Off Your Next Purchase','<p>Save $5 on your next visit to our restaurant. We appreciate your loyalty!</p>',6,'en','2024-12-19 19:32:31','2024-12-19 19:32:31'),(13,'وجبة أطفال مجانية','<p>أحضر أطفالك واستمتع بوجبة مجانية للأطفال عند شراء أي طبق رئيسي للبالغين.</p>',7,'ar','2024-12-19 19:32:31','2024-12-19 19:32:31'),(14,'Free Kids Meal','<p>Bring the little ones and enjoy a free kids meal with the purchase of any adult entrée.</p>',7,'en','2024-12-19 19:32:31','2024-12-19 19:32:31'),(15,'تذوق النبيذ مجانًا','<p>انضم إلينا في حدث مجاني لتذوق النبيذ. تذوق مجموعة مختارة من النبيذ الفاخر مجانًا!</p>',8,'ar','2024-12-19 19:32:31','2024-12-19 19:32:31'),(16,'Complimentary Wine Tasting','<p>Join us for a complimentary wine tasting event. Savor a selection of fine wines on us!</p>',8,'en','2024-12-19 19:32:31','2024-12-19 19:32:31'),(17,'وصول كبار الشخصيات إلى المناسبات الخاصة','<p>احصل على وصول حصري لكبار الشخصيات إلى فعالياتنا وعروضنا الترويجية الخاصة. كن أول من يعلم!</p>',9,'ar','2024-12-19 19:32:31','2024-12-19 19:32:31'),(18,'VIP Access to Special Events','<p>Get exclusive VIP access to our special events and promotions. Be the first to know!</p>',9,'en','2024-12-19 19:32:31','2024-12-19 19:32:31'),(19,'وجبة فطور مجانية لشخصين','<p>استمتع بوجبة فطور وغداء مجانية لشخصين مجانًا. واستمتع بقائمة وجبة فطور وغداء لذيذة مع صديق أو أحد أحبائك.</p>',10,'ar','2024-12-19 19:32:31','2024-12-19 19:32:31'),(20,'Free Brunch for Two','<p>Enjoy a free brunch for two on us. Indulge in our delicious brunch menu with a friend or loved one.</p>',10,'en','2024-12-19 19:32:31','2024-12-19 19:32:31');
/*!40000 ALTER TABLE `gift_translations` ENABLE KEYS */;
UNLOCK TABLES;

