INSERT INTO `location_translations` (`id`, `title`, `description`, `location_id`, `locale`, `created_at`, `updated_at`) VALUES (1,'الزمالك','<p>يشتهر الزمالك بمقاهيه ومطاعمه العصرية، ويقدم مجموعة متنوعة من خيارات الطعام بدءًا من المطاعم الراقية وحتى الأماكن غير الرسمية.</p>',1,'ar','2024-12-19 19:32:18','2024-12-19 19:32:18'),(2,'Zamalek','<p>Known for its trendy cafes and restaurants, Zamalek offers a variety of dining options from upscale eateries to casual spots.</p>',1,'en','2024-12-19 19:32:18','2024-12-19 19:32:18'),(3,'وسط القاهرة','<p>القلب التاريخي للمدينة، ويقدم مزيجًا من المأكولات المصرية التقليدية وخيارات تناول الطعام العالمية.</p>',2,'ar','2024-12-19 19:32:18','2024-12-19 19:32:18'),(4,'Downtown Cairo','<p>The historic heart of the city, offering a mix of traditional Egyptian cuisine and international dining options.</p>',2,'en','2024-12-19 19:32:18','2024-12-19 19:32:18'),(5,'المعادي','<p>منطقة ضاحية مليئة بالأشجار تشتهر بمجموعة متنوعة من المطاعم، بدءًا من المقاهي المريحة وحتى تجارب تناول الطعام الفاخرة.</p>',3,'ar','2024-12-19 19:32:18','2024-12-19 19:32:18'),(6,'Maadi','<p>A leafy suburban area known for its diverse range of restaurants, from cozy cafes to gourmet dining experiences.</p>',3,'en','2024-12-19 19:32:18','2024-12-19 19:32:18'),(7,'مصر الجديدة','<p>تتميز هذه المنطقة بمزيج من المطاعم الحديثة والتقليدية، وتوفر مجموعة واسعة من خيارات الطهي.</p>',4,'ar','2024-12-19 19:32:18','2024-12-19 19:32:18'),(8,'Heliopolis','<p>This district features a blend of modern and traditional restaurants, providing a wide array of culinary choices.</p>',4,'en','2024-12-19 19:32:18','2024-12-19 19:32:18'),(9,'القاهرة الجديدة','<p>منطقة سريعة النمو تضم العديد من المطاعم الجديدة التي تقدم المأكولات المحلية والعالمية.</p>',5,'ar','2024-12-19 19:32:18','2024-12-19 19:32:18'),(10,'New Cairo','<p>A rapidly growing area with numerous new dining establishments, offering both local and international cuisine.</p>',5,'en','2024-12-19 19:32:18','2024-12-19 19:32:18'),(11,'جاردن سيتي','<p>منطقة خلابة تضم مطاعم ساحرة، وغالبًا ما تقع في مباني تاريخية.</p>',6,'ar','2024-12-19 19:32:18','2024-12-19 19:32:18'),(12,'Garden City','<p>A picturesque area with charming restaurants, often housed in historic buildings.</p>',6,'en','2024-12-19 19:32:18','2024-12-19 19:32:18'),(13,'المهندسين','<p>يشتهر بأجوائه الصاخبة وتنوع خيارات تناول الطعام، بدءًا من الوجبات السريعة وحتى المطاعم الفاخرة.</p>',7,'ar','2024-12-19 19:32:18','2024-12-19 19:32:18'),(14,'Mohandessin','<p>Known for its bustling atmosphere and variety of dining options, from quick bites to fine dining.</p>',7,'en','2024-12-19 19:32:18','2024-12-19 19:32:18'),(15,'مدينة ناصر','<p>يقدم مجموعة من المطاعم، والتي تحظى بشعبية خاصة لتناول الطعام المناسب للعائلات وصالات الطعام الكبيرة.</p>',8,'ar','2024-12-19 19:32:18','2024-12-19 19:32:18'),(16,'Nasr City','<p>Offers a range of restaurants, particularly popular for its family-friendly dining and large food courts.</p>',8,'en','2024-12-19 19:32:18','2024-12-19 19:32:18'),(17,'حديقة الأزهر','<p>موقع خلاب يضم مطاعم تقدم مناظر خلابة للمدينة ومأكولات لذيذة.</p>',9,'ar','2024-12-19 19:32:18','2024-12-19 19:32:18'),(18,'Al Azhar Park','<p>A scenic location with restaurants that offer stunning views of the city and delicious food.</p>',9,'en','2024-12-19 19:32:18','2024-12-19 19:32:18'),(19,'مدينة الشيخ زايد','<p>ضاحية راقية تضم عددًا متزايدًا من المطاعم والمقاهي عالية الجودة التي تلبي الأذواق الراقية.</p>',10,'ar','2024-12-19 19:32:18','2024-12-19 19:32:18'),(20,'Sheikh Zayed City','<p>An upscale suburb with a growing number of high-quality restaurants and cafes, catering to a sophisticated palate.</p>',10,'en','2024-12-19 19:32:18','2024-12-19 19:32:18');
/*!40000 ALTER TABLE `location_translations` ENABLE KEYS */;
UNLOCK TABLES;

