INSERT INTO `meal_translations` (`id`, `title`, `description`, `meal_id`, `locale`, `created_at`, `updated_at`) VALUES (3,'بيتزا مارغريتا','<p>بيتزا إيطالية كلاسيكية مغطاة بالطماطم الطازجة، جبنة الموزاريلا والريحان.</p>',2,'ar','2024-12-19 19:32:22','2024-12-19 19:32:22'),(4,'Margherita Pizza','<p>Classic Italian pizza topped with fresh tomatoes, mozzarella, and basil.</p>',2,'en','2024-12-19 19:32:22','2024-12-19 19:32:22'),(5,'برجر لحم','<p>قطعة لحم بقري طري مع الخس، الطماطم، البصل والصلصة الخاصة على خبز محمص.</p>',3,'ar','2024-12-19 19:32:22','2024-12-19 19:32:22'),(6,'Beef Burger','<p>Juicy beef patty with lettuce, tomato, onion, and special sauce on a toasted bun.</p>',3,'en','2024-12-19 19:32:22','2024-12-19 19:32:22'),(7,'القلي النباتي','<p>خضروات مشكلة طازجة مقلية في صلصة مالحة.</p>',4,'ar','2024-12-19 19:32:22','2024-12-19 19:32:22'),(8,'Vegetable Stir-Fry','<p>Fresh mixed vegetables stir-fried in a savory sauce.</p>',4,'en','2024-12-19 19:32:22','2024-12-19 19:32:22'),(9,'سلمون مشوي','<p>فيليه سمك السلمون الطري المشوي يقدم مع صلصة الليمون والزبدة.</p>',5,'ar','2024-12-19 19:32:22','2024-12-19 19:32:22'),(10,'Grilled Salmon','<p>Tender grilled salmon fillet served with lemon butter sauce.</p>',5,'en','2024-12-19 19:32:22','2024-12-19 19:32:22'),(11,'سباغيتي كاربونارا','<p>طبق باستا إيطالي كلاسيكي مع صلصة البيض الكريمية واللحم المقدد وجبنة البارميزان.</p>',6,'ar','2024-12-19 19:32:22','2024-12-19 19:32:22'),(12,'Spaghetti Carbonara','<p>Classic Italian pasta dish with creamy egg sauce, bacon, and Parmesan cheese.</p>',6,'en','2024-12-19 19:32:22','2024-12-19 19:32:22'),(13,'ريزوتو الفطر','<p>أرز الريسوتو الكريمي المطبوخ مع الفطر والثوم والنبيذ الأبيض.</p>',7,'ar','2024-12-19 19:32:22','2024-12-19 19:32:22'),(14,'Mushroom Risotto','<p>Creamy risotto rice cooked with mushrooms, garlic, and white wine.</p>',7,'en','2024-12-19 19:32:22','2024-12-19 19:32:22'),(15,'سلطانية بoke هاواي','<p>سمك نيء طازج متبل بصلصة الصويا وزيت السمسم والبهارات، يقدم فوق الأرز مع الخضار.</p>',8,'ar','2024-12-19 19:32:22','2024-12-19 19:32:22'),(16,'Hawaiian Poke Bowl','<p>Fresh raw fish marinated in soy sauce, sesame oil, and spices, served over rice with vegetables.</p>',8,'en','2024-12-19 19:32:22','2024-12-19 19:32:22'),(17,'فاهيتا لحم البقر','<p>مقلاة ساخنة مكونة من شرائح اللحم البقري المشوي والفلفل الحلو والبصل، تقدم مع خبز التورتيلا والجواكامولي والصلصة.</p>',9,'ar','2024-12-19 19:32:22','2024-12-19 19:32:22'),(18,'Beef Fajitas','<p>Sizzling hot skillet of grilled beef strips, bell peppers, and onions, served with tortillas, guacamole, and salsa.</p>',9,'en','2024-12-19 19:32:22','2024-12-19 19:32:22'),(19,'سلطة سيزر','<p>خس روماني مقرمش، خبز محمص بالثوم، جبنة بارميزان وصلصة سيزر.</p>',10,'ar','2024-12-19 19:32:22','2024-12-19 19:32:22'),(20,'Caesar Salad','<p>Crisp romaine lettuce, garlic croutons, Parmesan cheese, and Caesar dressing.</p>',10,'en','2024-12-19 19:32:22','2024-12-19 19:32:22'),(21,'تاكو الروبيان','<p>تورتيلا طرية محشوة بالروبيان المتبل والمشوي، مغطاة بالكزبرة الطازجة وكرنب مبشور وكريمة لايم منعشة.</p>',11,'ar','2024-12-19 19:32:22','2024-12-19 19:32:22'),(22,'Shrimp Tacos','<p>Soft tortillas filled with seasoned and grilled shrimp, topped with fresh cilantro, cabbage slaw, and a tangy lime crema.</p>',11,'en','2024-12-19 19:32:22','2024-12-19 19:32:22'),(23,'ساندويتش لحم الخنزير المشوي بالباربيكيو','<p>لحم خنزير مشوي ببطء في صلصة باربيكيو لذيذة، يقدم في خبز محمص مع كولسلو ومخللات.</p>',12,'ar','2024-12-19 19:32:22','2024-12-19 19:32:22'),(24,'BBQ Pulled Pork Sandwich','<p>Slow-cooked pulled pork in a savory BBQ sauce, served on a toasted bun with coleslaw and pickles.</p>',12,'en','2024-12-19 19:32:22','2024-12-19 19:32:22'),(25,'طاجين لحم الضأن المغربي','<p>يخنة عطرية وشهية من لحم الضأن والمشمش واللوز، مطهوة بتوابل مغربية وتقدم مع الكسكس.</p>',13,'ar','2024-12-19 19:32:22','2024-12-19 19:32:22'),(26,'Moroccan Lamb Tagine','<p>A fragrant and hearty stew of lamb, apricots, and almonds, cooked with Moroccan spices and served with couscous.</p>',13,'en','2024-12-19 19:32:22','2024-12-19 19:32:22'),(27,'موساكا يونانية','<p>كسرولة باذنجان بطبقات من اللحم المفروم المتبل وصلصة البشاميل الكريمية، مخبوزة حتى الكمال.</p>',14,'ar','2024-12-19 19:32:22','2024-12-19 19:32:22'),(28,'Greek Moussaka','<p>Layered eggplant casserole with spiced ground meat and a creamy béchamel sauce, baked to perfection.</p>',14,'en','2024-12-19 19:32:22','2024-12-19 19:32:22'),(29,'دجاج سzechuan','<p>دجاج بنمط سيشوان الحار مع الفلفل الحلو والبصل والفول السوداني، يقدم مع أرز أبيض مطهو على البخار.</p>',15,'ar','2024-12-19 19:32:22','2024-12-19 19:32:22'),(30,'Szechuan Chicken','<p>Spicy Szechuan-style chicken stir-fried with bell peppers, onions, and peanuts, served with steamed white rice.</p>',15,'en','2024-12-19 19:32:22','2024-12-19 19:32:22'),(31,'باييلا الخضار','<p>طبق أرز إسباني نابض بالحياة مطهو بالزعفران والخضروات المختلطة والخرشوف، مزين بالبقدونس الطازج.</p>',16,'ar','2024-12-19 19:32:22','2024-12-19 19:32:22'),(32,'Vegetable Paella','<p>A vibrant Spanish rice dish cooked with saffron, mixed vegetables, and artichokes, garnished with fresh parsley.</p>',16,'en','2024-12-19 19:32:22','2024-12-19 19:32:22'),(33,'دجاج تيكا ماسالا','<p>قطع دجاج طرية في صلصة طماطم متبلة وكريمية، تقدم مع أرز بسمتي وخبز النان.</p>',17,'ar','2024-12-19 19:32:22','2024-12-19 19:32:22'),(34,'Chicken Tikka Masala','<p>Tender pieces of chicken in a creamy, spiced tomato sauce, served with basmati rice and naan bread.</p>',17,'en','2024-12-19 19:32:22','2024-12-19 19:32:22'),(35,'حساء لوبستر بيسك','<p>حساء غني وكريمي مصنوع من اللوبستر الطازج والخضروات العطرية ولمسة من الشيري.</p>',18,'ar','2024-12-19 19:32:22','2024-12-19 19:32:22'),(36,'Lobster Bisque','<p>A rich and creamy soup made with fresh lobster, aromatic vegetables, and a touch of sherry.</p>',18,'en','2024-12-19 19:32:22','2024-12-19 19:32:22'),(37,'راتاتوي','<p>طبق خضروات مطهو تقليدي من بروفانس الفرنسية يتكون من الكوسة والباذنجان والفلفل الحلو والطماطم.</p>',19,'ar','2024-12-19 19:32:22','2024-12-19 19:32:22'),(38,'Ratatouille','<p>A traditional French Provençal stewed vegetable dish consisting of zucchini, eggplant, bell peppers, and tomatoes.</p>',19,'en','2024-12-19 19:32:22','2024-12-19 19:32:22'),(39,'لحم بقر بولجوجي الكوري','<p>شرائح لحم بقر رقيقة متبلة في صلصة حلوة ومالحة، مشوية حتى الكمال وتقدم مع أرز مطهو على البخار وكيمتشي.</p>',20,'ar','2024-12-19 19:32:22','2024-12-19 19:32:22'),(40,'Korean Beef Bulgogi','<p>Thinly sliced beef marinated in a savory-sweet sauce, grilled to perfection, and served with steamed rice and kimchi.</p>',20,'en','2024-12-19 19:32:22','2024-12-19 19:32:22'),(41,'دجاج بالكريمة الحمراء','<p>طبق فرنسي كلاسيكي من الدجاج مطهو بالنبيذ الأحمر مع الفطر والبصل واللحم المقدد.</p>',21,'ar','2024-12-19 19:32:22','2024-12-19 19:32:22'),(42,'Coq au Vin','<p>A classic French dish of chicken braised in red wine with mushrooms, onions, and bacon.</p>',21,'en','2024-12-19 19:32:22','2024-12-19 19:32:22'),(43,'غومبو المأكولات البحرية','<p>يخنة لذيذة من لويزيانا مصنوعة من الجمبري والسلطعون والنقانق والبامية ومرقة غنية مبنية على الرو، تقدم فوق الأرز.</p>',22,'ar','2024-12-19 19:32:22','2024-12-19 19:32:22'),(44,'Seafood Gumbo','<p>A flavorful stew from Louisiana made with shrimp, crab, sausage, okra, and a rich roux-based broth, served over rice.</p>',22,'en','2024-12-19 19:32:22','2024-12-19 19:32:22'),(45,'طبق فلافل','<p>كرات فلافل مقرمشة تقدم مع حمص وتبولة وخضروات مخللة وخبز بي.</p>',23,'ar','2024-12-19 19:32:22','2024-12-19 19:32:22'),(46,'Falafel Platter','<p>Crispy falafel balls served with hummus, tabbouleh, pickled vegetables, and warm pita bread.</p>',23,'en','2024-12-19 19:32:22','2024-12-19 19:32:22'),(47,'بط مع صلصة البرتقال','<p>صدر البط المحمص مع صلصة البرتقال المنعشة، يقدم مع بطاطا مشوية وفاصوليا خضراء.</p>',24,'ar','2024-12-19 19:32:22','2024-12-19 19:32:22'),(48,'Duck à l\'Orange','<p>Roasted duck breast glazed with a tangy orange sauce, served with roasted potatoes and green beans.</p>',24,'en','2024-12-19 19:32:22','2024-12-19 19:32:22'),(49,'بانير بوتير ماسالا','<p>جبن هندي مطهو في صلصة طماطم كريمية وغنية، يقدم مع أرز بسمتي وخبز النان.</p>',25,'ar','2024-12-19 19:32:22','2024-12-19 19:32:22'),(50,'Paneer Butter Masala','<p>Indian cottage cheese cooked in a rich and creamy tomato-based sauce, served with basmati rice and naan.</p>',25,'en','2024-12-19 19:32:22','2024-12-19 19:32:22');
