INSERT INTO `news_translations` (`id`, `title`, `subtitle`, `description`, `news_id`, `locale`, `created_at`, `updated_at`) VALUES (1,'تمكين نيوز','ابق على اطلاع، ابق ملهمًا','<p>اكتشف أحدث المشاركات والتحديثات في عالم اللياقة البدنية مع تمكين نيوز. بدءًا من أحدث اتجاهات التمارين الرياضية والإنجازات الغذائية إلى قصص النجاح داخل مجتمعنا، نقدم لك مجموعة مختارة من الأخبار التي تحفزك وتعلمها. سواء كنت تبحث عن نصائح للياقة البدنية ، وقصص النجاح، أو السبق الصحفي الداخلي حول الأحداث القادمة، تمكين نيوز هو مصدرك المفضل لكل ما يتعلق باللياقة البدنية. قم بتغذية رحلتك، وابق على اتصال، وكن جزءًا من ثورة اللياقة البدنية!</p>',1,'ar','2024-12-19 19:32:22','2024-12-19 19:32:22'),(2,'EmpowerNews','Stay Informed, Stay Inspired','<p>Discover the latest buzz and updates in the fitness world with EmpowerNews. From cutting-edge workout trends and nutrition breakthroughs to success stories within our community, we bring you a curated selection of news that motivates and informs. Whether you\'re seeking fitness tips, success stories, or the inside scoop on upcoming events, EmpowerNews is your go-to source for all things fitness. Fuel your journey, stay connected, and be part of the fitness revolution!</p>',1,'en','2024-12-19 19:32:22','2024-12-19 19:32:22'),(3,'فت فلاش','نبضك على اتجاهات اللياقة البدنية','<p>ابق متقدمًا في لعبة اللياقة البدنية مع فت فلاش، مصدرك النهائي لأحدث الأحداث في صالة الألعاب الرياضية، والإنجازات الصحية، وقصص النجاح. استكشف إجراءات التمرين الديناميكية والرؤى الغذائية وأضواء المجتمع التي تلهم وترفع مستوى الأداء. بدءًا من إعلانات الأحداث المثيرة وحتى المقابلات مع الخبراء، يبقيك فت فلاش على اتصال بنبض مجتمع اللياقة البدنية لدينا. احصل على جرعة يومية من التحفيز والتعليم والتمكين. لأننا في نجوم العالم، لا نهتم فقط بالتدريبات؛ نحن نتحدث عن أسلوب حياة يغذي أفضل ما لديك.</p>',2,'ar','2024-12-19 19:32:22','2024-12-19 19:32:22'),(4,'FitFlash','Your Pulse on Fitness Trends','<p>Stay ahead in the fitness game with FitFlash, your ultimate source for the latest gym happenings, wellness breakthroughs, and success stories. Explore dynamic workout routines, nutritional insights, and community spotlights that inspire and elevate. From exciting event announcements to expert interviews, FitFlash keeps you connected to the pulse of our fitness community. Tune in for a daily dose of motivation, education, and empowerment. Because at World PT Superstars, we\'re not just about workouts; we\'re about a lifestyle that fuels your best self.</p>',2,'en','2024-12-19 19:32:22','2024-12-19 19:32:22'),(5,'ملخص اللياقة البدنية','تقرير العافية الأسبوعي الخاص بك','<p>مرحبًا بك في FitnessFusion Digest، حيث ننظم أحدث وأكبر ما في عالم اللياقة البدنية والصحة والمجتمع. ابق على اطلاع بأحدث التدريبات واتجاهات التغذية وقصص النجاح الملهمة. بدءًا من الأحداث الرياضية المثيرة وحتى المقابلات مع الخبراء، نقدم لك نظرة شاملة لأسلوب حياة اللياقة البدنية. انضم إلينا في رحلة العافية هذه، حيث تم تصميم كل إصدار لتمكين تجربة اللياقة البدنية لديك وتحفيزها والارتقاء بها. مصدرك لكل ما يتعلق باللياقة البدنية، مباشرة من قلب نجوم العالم.</p>',3,'ar','2024-12-19 19:32:22','2024-12-19 19:32:22'),(6,'FitnessFusion Digest','Your Weekly Wellness Roundup','<p>Welcome to FitnessFusion Digest, where we curate the latest and greatest in the world of fitness, health, and community. Stay on the pulse of cutting-edge workouts, nutrition trends, and success stories that inspire. From exciting gym events to expert interviews, we bring you a holistic view of the fitness lifestyle. Join us on this wellness journey, where each edition is crafted to empower, motivate, and elevate your fitness experience. Your source for all things fitness, straight from the heart of World PT Superstars.</p>',3,'en','2024-12-19 19:32:22','2024-12-19 19:32:22');
/*!40000 ALTER TABLE `news_translations` ENABLE KEYS */;
UNLOCK TABLES;

