INSERT INTO `opportunity_translations` (`id`, `title`, `subtitle`, `description`, `opportunity_id`, `locale`, `created_at`, `updated_at`) VALUES (1,'???? ???? ?????????????? ???????? ???????????? ???????????????? ???? ?????? ????????????????',NULL,'???????????????? ?????????? ?????????? ???????????????? ?????????????????? ?????????????? ?????????????? ?????? ???????? ???????????? ???????????? ???????????? ???????????? ??????????????????. ???????? ?????????? ?????? ?????????? ???????????????? ?????????? ?????????? ?????????????? ????????????.',1,'ar','2024-12-19 19:32:22','2024-12-19 19:32:22'),(2,'What advantages do your trucks offer in terms of efficiency?',NULL,'<p>Our trucks are equipped with cutting-edge technology and fuel-efficient engines, ensuring optimal performance and reduced carbon footprint. This translates to cost savings and eco-friendly transportation solutions.</p>',1,'en','2024-12-19 19:32:22','2024-12-19 19:32:22'),(3,'?????? ???????? ???????????? ?????????????? ???? ?????????? ????????????????',NULL,'???????? ?????? ?????????????? ?????????????? ???????? ???????????????????? ?????? ???????? ?????????? ???????????? ?????????????????? ?????????? ???????????????? ???????????????? ??????????????. ???????? ???????? ?????? ???????? ?????????????? ???? ?????????? ?????????????? ?????????????? ?????????????????? ???????????????? ????????.',2,'ar','2024-12-19 19:32:22','2024-12-19 19:32:22'),(4,'How does your fleet ensure timely deliveries?',NULL,'<p>Our strategically managed fleet, coupled with advanced tracking systems, allows us to optimize routes and schedules. This enables us to guarantee punctual deliveries, meeting deadlines with precision.</p>',2,'en','2024-12-19 19:32:22','2024-12-19 19:32:22'),(5,'?????? ???????? ?????????? ?????????????? ?????????? ??????????????????',NULL,'?????? ?????????????? ???????????????? ?????????? ??????????????????. ?????? ?????????? ?????????????? ?????????????? ???????????? ?????????????? ???????????? ???? ?????????