INSERT INTO `page_translations` (`id`, `title`, `subtitle`, `description`, `page_id`, `locale`, `created_at`, `updated_at`) VALUES (1,NULL,'قصتنا للتميز في الطهي في ريسيرفيا','<p>هناك العديد من الأنواع المتوفرة لنصوص لوريم إيبسوم، لكن الأغلبية عانوا من التغيير بشكل ما، عن طريق إدخال الفكاهة، أو العثور على كلمات عشوائية لا تبدو قابلة للتصديق ولو قليلاً.\n                            أكثر من 20 عامًا من الخبرة في تقديم خدمات حجز المنازل عالية الجودة وبيعها لتحقيق حلمك المذهل وجعلك سعيدًا</p>',1,'ar','2024-12-19 19:32:18','2024-12-19 19:32:18'),(2,NULL,'Our Story of food Culinary Excellence at Reservya','<p>There are many variations of passages of Lorem Ipsum available, but the to a majority have suffered alteration in some form, by injected humour, or find randomised words which don\'t look even slightly believable.\n                            Over 20 years’ experience providing top quality house Booking rant and sell for your Amazing Dream & Make you Happy</p>',1,'en','2024-12-19 19:32:18','2024-12-19 19:32:18'),(3,'الأسئلة الشائعة حول عشاق الطعام: تمت الإجابة على استفساراتكم المتعلقة بالطهي',NULL,NULL,2,'ar','2024-12-19 19:32:18','2024-12-19 19:32:18'),(4,'Foodie FAQ: Your Culinary Queries Answered',NULL,NULL,2,'en','2024-12-19 19:32:18','2024-12-19 19:32:18');
