INSERT INTO `service_translations` (`id`, `title`, `service_id`, `locale`, `created_at`, `updated_at`) VALUES (3,'توصيل الطعام مباشرة إلى منازل العملاء أو مكاتبهم.',2,'ar','2024-12-19 19:32:18','2024-12-19 19:32:18'),(4,'Delivering food directly to customers\' homes or offices.',2,'en','2024-12-19 19:32:18','2024-12-19 19:32:18'),(5,'السماح للعملاء بطلب واستلام طعامهم لتناوله في مكان آخر.',3,'ar','2024-12-19 19:32:18','2024-12-19 19:32:18'),(6,'Allowing customers to order and pick up their food to eat elsewhere.',3,'en','2024-12-19 19:32:18','2024-12-19 19:32:18'),(7,'نقدم تجارب حصرية لتناول الطعام في غرف خاصة للمناسبات الخاصة أو اجتماعات الشركات.',4,'ar','2024-12-19 19:32:18','2024-12-19 19:32:18'),(8,'Offering exclusive dining experiences in private rooms for special events or corporate meetings.',4,'en','2024-12-19 19:32:18','2024-12-19 19:32:18'),(9,'تمكين العملاء من حجز الطاولات عبر الإنترنت من خلال الموقع الإلكتروني للمطعم أو منصات الطرف الثالث.',5,'ar','2024-12-19 19:32:18','2024-12-19 19:32:18'),(10,'Enabling customers to book tables online through the restaurant\'s website or third-party platforms.',5,'en','2024-12-19 19:32:18','2024-12-19 19:32:18'),(11,'استضافة المناسبات مثل حفلات أعياد الميلاد وحفلات الزفاف ومناسبات الشركات والتجمعات الاجتماعية الأخرى.',6,'ar','2024-12-19 19:32:18','2024-12-19 19:32:18'),(12,'Hosting events such as birthday parties, weddings, corporate events, and other social gatherings.',6,'en','2024-12-19 19:32:18','2024-12-19 19:32:18'),(13,'تحضير وجبات الطعام مسبقًا ليأخذها العملاء إلى المنزل ويستمتعون بها طوال الأسبوع.',7,'ar','2024-12-19 19:32:18','2024-12-19 19:32:18'),(14,'Preparing meals in advance for customers to take home and enjoy throughout the week.',7,'en','2024-12-19 19:32:18','2024-12-19 19:32:18'),(15,'نقدم نبيذًا ومشروبات متخصصة مع وجبات الطعام، غالبًا مع سقاة خبراء.',8,'ar','2024-12-19 19:32:18','2024-12-19 19:32:18'),(16,'Offering specialized wine and beverage pairings with meals, often with expert sommeliers.',8,'en','2024-12-19 19:32:18','2024-12-19 19:32:18'),(17,'توفير دروس حيث يمكن للعملاء تعلم طهي أطباق أو مأكولات معينة.',9,'ar','2024-12-19 19:32:18','2024-12-19 19:32:18'),(18,'Providing classes where customers can learn to cook specific dishes or cuisines.',9,'en','2024-12-19 19:32:18','2024-12-19 19:32:18'),(19,'إنشاء قوائم خاصة للعطلات أو المواسم أو المناسبات الخاصة، غالبًا ما تحتوي على أطباق أو سمات فريدة.',10,'ar','2024-12-19 19:32:18','2024-12-19 19:32:18'),(20,'Creating special menus for holidays, seasons, or special events, often with unique dishes or themes.',10,'en','2024-12-19 19:32:18','2024-12-19 19:32:18');
