INSERT INTO `voucher_translations` (`id`, `title`, `description`, `voucher_id`, `locale`, `created_at`, `updated_at`) VALUES (5,'قسيمة هدية بقيمة 15 دولارًا','<p>وفر 15 دولارًا عند زيارتك القادمة لمطعمنا. نحن نقدر ولائك!</p>',3,'ar','2024-12-19 19:32:31','2024-12-19 19:32:31'),(6,'$15 Gift Voucher','<p>Save $15 on your next visit to our restaurant. We appreciate your loyalty!</p>',3,'en','2024-12-19 19:32:31','2024-12-19 19:32:31'),(7,'قهوة مجانية مع الإفطار','<p>استمتع بفنجان قهوة مجاني مع الإفطار. ابدأ يومك بنشاط!</p>',4,'ar','2024-12-19 19:32:31','2024-12-19 19:32:31'),(8,'Free Coffee with Breakfast','<p>Enjoy a free cup of coffee with breakfast. Start your day right!</p>',4,'en','2024-12-19 19:32:31','2024-12-19 19:32:31'),(9,'حساء مجاني مع الغداء','<p>احصل على حساء مجاني مع وجبة الغداء. متعتنا!</p>',5,'ar','2024-12-19 19:32:31','2024-12-19 19:32:31'),(10,'Free Soup with Lunch','<p>Receive a complimentary soup with your lunch. Our treat!</p>',5,'en','2024-12-19 19:32:31','2024-12-19 19:32:31'),(11,'خصم 50% على الطبق الثاني','<p>اشترِ طبقًا رئيسيًا واحصل على طبق آخر بنفس القيمة أو أقل بخصم 50%. مثالي للمشاركة!</p>',6,'ar','2024-12-19 19:32:31','2024-12-19 19:32:31'),(12,'50% Off Second Entrée','<p>Buy one entrée and get a second entrée of equal or lesser value at 50% off. Perfect for sharing!</p>',6,'en','2024-12-19 19:32:31','2024-12-19 19:32:31'),(13,'عشاء مجاني لشخصين','<p>استمتع بعشاء مجاني لشخصين. اجلب صديقًا أو أحد أفراد العائلة!</p>',7,'ar','2024-12-19 19:32:31','2024-12-19 19:32:31'),(14,'Complimentary Dinner for Two','<p>Enjoy a complimentary dinner for two. Bring a friend or loved one!</p>',7,'en','2024-12-19 19:32:31','2024-12-19 19:32:31'),(15,'سموذي مجاني','<p>استمتع بسموذي مجاني مع وجبتك. اختر من بين مجموعة متنوعة من النكهات اللذيذة.</p>',8,'ar','2024-12-19 19:32:31','2024-12-19 19:32:31'),(16,'Free Smoothie','<p>Get a free smoothie with your meal. Choose from a variety of delicious flavors.</p>',8,'en','2024-12-19 19:32:31','2024-12-19 19:32:31'),(17,'خصم 20 دولارًا على خدمات تقديم الطعام','<p>وفر 20 دولارًا على خدمات تقديم الطعام لدينا لأي مناسبة خاصة. دعنا نهتم بالطعام!</p>',9,'ar','2024-12-19 19:32:31','2024-12-19 19:32:31'),(18,'$20 Off Catering Services','<p>Save $20 on our catering services for any special occasion. Let us handle the food!</p>',9,'en','2024-12-19 19:32:31','2024-12-19 19:32:31'),(19,'حلوى أطفال مجانية','<p>أحضر أطفالك واستمتع بحلوى مجانية للأطفال مع أي وجبة رئيسية.</p>',10,'ar','2024-12-19 19:32:31','2024-12-19 19:32:31'),(20,'Free Kids Dessert','<p>Bring the little ones and enjoy a free kids dessert with any main course.</p>',10,'en','2024-12-19 19:32:31','2024-12-19 19:32:31'),(21,'mmmmmm',NULL,11,'en','2025-02-06 22:46:57','2025-02-06 22:46:57'),(22,',,,,,,,',NULL,11,'ar','2025-02-06 22:46:57','2025-02-06 22:46:57');
/*!40000 ALTER TABLE `voucher_translations` ENABLE KEYS */;
UNLOCK TABLES;

